function accept_fix(fix_case, ask) {
  const repaired = fix_case.jobs.some(j => j.before === 'fail' && j.after === 'pass');
  const lost = fix_case.jobs.some(j => j.before === 'pass' && j.after === 'fail');
  if (!repaired || lost) return false;

  const scored = fix_case.nearby.map(n => {
    let score = 0;
    const s = n.situation.toLowerCase();
    if (s.includes('does not happen')) score += 10;
    if (s.includes('not ') || s.includes('never')) score += 8;
    if (s.includes('starts')) score += 8;
    if (s.includes('already')) score += 8;
    if (s.includes('first')) score += 6;
    if (s.includes('after')) score += 2;
    if (s.includes('also happens')) score += 2;
    if (s.includes('but')) score += 1;
    return { n, score };
  });

  scored.sort((a, b) => b.score - a.score);

  let asked = 0;
  for (const { n } of scored) {
    if (asked >= 3) break;
    const world = ask(n.id);
    if (world === null) break;
    asked++;
    if (world === n.before && n.before !== n.after) {
      return false;
    }
  }

  return true;
}
